class Solution {
    public long sumScores(String s) {
        int n = s.length();
        char[] c = s.toCharArray();
        int[] z = new int[n];
        z[0] = n;
        int l = 0, r = 0;
        for (int i = 1; i < n; i++) {
            if (i < r) z[i] = Math.min(r - i, z[i - l]);
            while (i + z[i] < n && c[z[i]] == c[i + z[i]]) z[i]++;
            if (i + z[i] > r) { l = i; r = i + z[i]; }
        }
        long ans = 0;
        for (int v : z) ans += v;
        return ans;
    }
};

